// Rough cost comparison: peak-sized fleet running all day
// versus an autoscaled fleet tracking real demand
double peakInstances = 30;
double baselineInstances = 10;
double hourlyRatePerInstance = 0.50;

double flatCost = peakInstances * 24 * hourlyRatePerInstance;
double autoscaledCost =
    (baselineInstances * 20 * hourlyRatePerInstance) +
    (peakInstances * 4 * hourlyRatePerInstance);

System.out.println("Flat peak-sized cost: " + flatCost);       // 360.00
System.out.println("Autoscaled cost: " + autoscaledCost);      // 160.00

